func halve(prices []int) {
    for i := range prices {
        prices[i] /= 2
    }
}

func addTag(tags *[]string, tag string) {
    *tags = append(*tags, tag)
}

func main() {
    tags := []string{"go"}
    addTag(&tags, "cli")
    addTag(&tags, "tui")
    fmt.Println(tags, len(tags))
}

func push(s *[]int, n int) {
    *s = append(*s, n)
}

func pop(s *[]int) int {
    last := (*s)[len(*s)-1]
    *s = (*s)[:len(*s)-1]
    return last
}

func main() {
    nums := []int{1, 2}
    push(&nums, 3)
    push(&nums, 4)
    top := pop(&nums)
    fmt.Println(top, nums)
}

