type Task struct {
    name string
    done bool
}

func find(tasks []Task, name string) *Task {
    for i := range tasks {
        if tasks[i].name == name {
            return &tasks[i]
        }
    }
    return nil
}

tasks := []Task{{name: "write"}, {name: "test"}}
t := find(tasks, "test")
if t != nil {
    t.done = true
}
fmt.Println(tasks)
